#nullable enable
var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

List<TaskItem> tasks =
[
    new(1, "Design the logo", 3, false),
    new(2, "Write the README", 2, true),
];
var nextId = 3;

app.MapGet("/tasks", () => tasks);

app.MapGet("/tasks/{id:int}", (int id) =>
    tasks.FirstOrDefault(t => t.Id == id) is { } task
        ? Results.Ok(task)
        : Results.NotFound());

// TODO 1: bind CreateTask, not TaskItem, so
// clients can't pick the id or set done.
// TODO 2: answer ValidationProblem when
// Validate finds problems.
app.MapPost("/tasks", (CreateTask input) =>
{
    var errors = Validate(input.Title, input.Points);
    if (errors.Count > 0)
    {
        return Results.ValidationProblem(errors);
    }
    var task = new TaskItem(nextId++, input.Title, input.Points, false);
    tasks.Add(task);
    return Results.Created($"/tasks/{task.Id}", task);
});

// TODO 3: PUT /tasks/{id}: 404 if missing,
// validate, replace it, answer 204.
app.MapPut("/tasks/{id:int}", (int id, UpdateTask input) =>
{
    var index = tasks.FindIndex(t => t.Id == id);
    if (index < 0)
    {
        return Results.NotFound();
    }
    var errors = Validate(input.Title, input.Points);
    if (errors.Count > 0)
    {
        return Results.ValidationProblem(errors);
    }
    tasks[index] = new TaskItem(id, input.Title, input.Points, input.Done);
    return Results.NoContent();
});

// TODO 4: DELETE /tasks/{id}: 204, or 404.
app.MapDelete("/tasks/{id:int}", (int id) =>
    tasks.RemoveAll(t => t.Id == id) > 0
        ? Results.NoContent()
        : Results.NotFound());

app.Run();

static Dictionary<string, string[]> Validate(
    string? title, int points)
{
    var errors = new Dictionary<string, string[]>();
    if (string.IsNullOrWhiteSpace(title))
    {
        errors["title"] = ["Title is required."];
    }
    else if (title.Length > 40)
    {
        errors["title"] = ["Title can be at most 40 characters."];
    }
    if (points is < 1 or > 13)
    {
        errors["points"] = ["Points must be from 1 to 13."];
    }
    // TODO 2: errors["title"] =
    //   "Title is required." (missing or blank)
    //   "Title can be at most 40 characters."
    // errors["points"] =
    //   "Points must be from 1 to 13."
    return errors;
}

record TaskItem(
    int Id, string Title, int Points, bool Done);
record CreateTask(string Title, int Points);
record UpdateTask(
    string Title, int Points, bool Done);

